styles:
.guide-document {
  --ink: #17283d;
  --muted: #506176;
  --paper: #ffffff;
  --canvas: #f1f5fa;
  --line: #d9e2ed;
  --nav: #13263e;
  --nav-text: #d4e1ef;
  --blue: #2058a5;
  --blue-soft: #edf4ff;
  --teal: #076b63;
  --teal-soft: #eaf7f3;
  --amber: #86500a;
  --amber-soft: #fff6e6;
  --radius: 14px;
}
.guide-document * { box-sizing: border-box; }
.guide-document { scroll-behavior: smooth; scroll-padding-top: 24px; }
.guide-document { margin: 0; background: var(--canvas); color: var(--ink); font: 16px/1.7 -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; }
.guide-document a { color: var(--blue); text-underline-offset: 3px; }
.guide-document a:hover { text-decoration-thickness: 2px; }
.guide-document :focus-visible { outline: 3px solid #bd7100; outline-offset: 4px; }
.guide-document .skip-link { position: fixed; top: -100px; left: 16px; z-index: 10; padding: 10px 16px; background: white; color: var(--ink); }
.guide-document .skip-link:focus { top: 12px; }
.guide-document .layout { display: grid; grid-template-columns: 266px minmax(0, 1fr); }
.guide-document .sidebar { position: sticky; top: 0; height: 100vh; overflow-y: auto; padding: 30px 22px; background: var(--nav); color: var(--nav-text); }
.guide-document .brand { color: white; font-size: 22px; font-weight: 760; line-height: 1.25; }
.guide-document .sidebar .eyebrow { color: #93cfc9; }
.guide-document .sidebar p { margin: 8px 0 24px; font-size: 13px; color: #b7c7da; }
.guide-document .sidebar nav { display: grid; gap: 2px; }
.guide-document .sidebar nav a { padding: 7px 10px; border-radius: 7px; color: var(--nav-text); font-size: 13px; line-height: 1.5; text-decoration: none; }
.guide-document .sidebar nav a:hover, .guide-document .sidebar nav a:focus-visible { background: #25405f; color: white; }
.guide-document .nav-group { margin: 18px 10px 5px; color: #95aac4; font-size: 10px; font-weight: 750; letter-spacing: .12em; text-transform: uppercase; }
.guide-document .sidebar-foot { margin-top: 26px; padding-top: 16px; border-top: 1px solid #35506c; font-size: 12px; }
.guide-document .sidebar-foot a { color: #d4e1ef; }
.guide-document { min-width: 0; max-width: 1370px; padding: 38px 46px 64px; }
.guide-document .hero { padding: 42px; border: 1px solid #c9dbea; border-radius: 20px; background: linear-gradient(125deg, #ffffff 20%, #eaf4ff 72%, #e4f5ef); box-shadow: 0 12px 36px #142c4610; }
.guide-document .eyebrow { margin: 0 0 10px; color: var(--teal); font-size: 11px; font-weight: 800; letter-spacing: .14em; text-transform: uppercase; }
.guide-document h1 { max-width: 880px; margin: 10px 0 14px; font-size: clamp(32px, 4vw, 53px); line-height: 1.12; letter-spacing: -.045em; }
.guide-document .lead { max-width: 880px; margin: 0; color: #344d67; font-size: 19px; line-height: 1.65; }
.guide-document .badges, .guide-document .toolbar { display: flex; flex-wrap: wrap; gap: 9px; align-items: center; }
.guide-document .badges { margin: 24px 0 20px; }
.guide-document .badge { border: 1px solid #b9cedd; border-radius: 999px; background: #ffffffb8; padding: 4px 12px; font-size: 12px; font-weight: 700; }
.guide-document button, .guide-document .button { display: inline-flex; align-items: center; justify-content: center; border: 1px solid #b6c8dc; border-radius: 8px; padding: 9px 13px; background: white; color: var(--blue); font: inherit; font-size: 12px; font-weight: 700; text-decoration: none; cursor: pointer; }
.guide-document button:hover, .guide-document .button:hover { background: var(--blue-soft); }
.guide-document .button.primary { border-color: var(--blue); background: var(--blue); color: white; }
.guide-document .js-only { display: none; }
.guide-document .js-only { display: inline-flex; }
.guide-document .guide-controls { position: sticky; top: 0; z-index: 20; width: 100%; height: 56px; align-items: center; gap: 12px; padding: 8px 16px; border-bottom: 1px solid var(--line); background: var(--paper); }
.guide-document .guide-controls { display: flex; }
.guide-document .guide-controls-label { color: var(--muted); font-size: 12px; font-weight: 600; }
.guide-document .guide-controls > button, .guide-document .guide-controls > .button { flex-shrink: 0; white-space: nowrap; }
.guide-document { scroll-padding-top: 80px; }
.guide-document .sidebar[hidden] { display: none; }
.guide-document .layout.sidebar-collapsed { grid-template-columns: minmax(0, 1fr); }
.guide-document .layout.sidebar-collapsed main { width: 100%; margin-inline: auto; }
.guide-document .hero-note { margin: 18px 0 0; color: var(--muted); font-size: 12px; }
.guide-document section { margin-top: 28px; padding: 32px; border: 1px solid var(--line); border-radius: var(--radius); background: var(--paper); }
.guide-document h2 { margin: 0 0 16px; font-size: 27px; line-height: 1.3; letter-spacing: -.025em; }
.guide-document h3 { margin: 27px 0 10px; font-size: 20px; line-height: 1.4; }
.guide-document h4 { margin: 20px 0 8px; font-size: 16px; }
.guide-document p { margin: 10px 0 15px; }
.guide-document strong { font-weight: 720; }
.guide-document ul, .guide-document ol { margin: 10px 0 20px; padding-left: 23px; }
.guide-document li { margin: 7px 0; padding-left: 2px; }
.guide-document .section-top { display: flex; gap: 12px; align-items: center; margin-bottom: 8px; }
.guide-document .section-top .eyebrow { margin: 0; }
.guide-document .time { margin-left: auto; color: var(--muted); font-size: 11px; white-space: nowrap; }
.guide-document .grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 16px; margin: 20px 0; }
.guide-document .card { padding: 20px; border: 1px solid var(--line); border-radius: 10px; background: #f9fbfe; }
.guide-document .card h3 { margin: 0 0 9px; font-size: 17px; }
.guide-document .card p:last-child, .guide-document .callout p:last-child, .guide-document blockquote p:last-child { margin-bottom: 0; }
.guide-document .stage { margin: 23px 0; padding: 22px; border: 1px solid #c3d7e8; border-radius: 11px; background: #fbfdff; }
.guide-document .stage h3 { margin-top: 0; }
.guide-document .mini-flow { display: flex; align-items: center; gap: 10px; margin: 20px 0; }
.guide-document .flow-node { flex: 1 1 0; min-width: 0; padding: 13px 10px; border: 1px solid #b8cce1; border-radius: 8px; background: var(--blue-soft); text-align: center; font-size: 12px; line-height: 1.55; }
.guide-document .flow-node.added { border-color: #8cbdab; background: var(--teal-soft); }
.guide-document .flow-node strong { display: block; font-size: 13px; }
.guide-document .flow-arrow { flex: none; color: var(--blue); font-size: 22px; }
.guide-document .callout { margin: 20px 0; padding: 17px 20px; border-left: 4px solid var(--blue); border-radius: 0 9px 9px 0; background: var(--blue-soft); }
.guide-document .callout.good { border-color: var(--teal); background: var(--teal-soft); }
.guide-document .callout.warning { border-color: var(--amber); background: var(--amber-soft); }
.guide-document .callout .label { display: block; margin-bottom: 5px; color: var(--blue); font-size: 11px; font-weight: 800; letter-spacing: .06em; text-transform: uppercase; }
.guide-document .callout.good .label { color: var(--teal); }
.guide-document .callout.warning .label { color: var(--amber); }
.guide-document blockquote { margin: 18px 0; padding: 17px 22px; border-left: 4px solid var(--teal); background: #f4faf8; font-size: 16px; }
.guide-document blockquote .label { display: block; margin-bottom: 6px; color: var(--teal); font-size: 11px; font-weight: 800; letter-spacing: .06em; text-transform: uppercase; }
.guide-document .table-wrap { max-width: 100%; margin: 18px 0; overflow-x: auto; border: 1px solid var(--line); border-radius: 9px; }
.guide-document table { width: 100%; border-collapse: collapse; font-size: 13px; line-height: 1.65; }
.guide-document caption { padding: 12px 15px; text-align: left; color: var(--muted); font-size: 12px; background: #f8fafd; }
.guide-document th, .guide-document td { padding: 12px 14px; border-bottom: 1px solid var(--line); text-align: left; vertical-align: top; overflow-wrap: break-word; }
.guide-document thead th { background: #edf2f8; color: #314a65; font-weight: 750; }
.guide-document tbody th { min-width: 125px; color: var(--ink); font-weight: 700; }
.guide-document tr:last-child td, .guide-document tr:last-child th { border-bottom: 0; }
.guide-document tbody tr:nth-child(even) { background: #fbfcfe; }
.guide-document .number { white-space: nowrap; font-variant-numeric: tabular-nums; }
.guide-document code { border-radius: 4px; background: #edf2f8; padding: 2px 5px; font: .87em/1.6 ui-monospace, SFMono-Regular, Consolas, monospace; overflow-wrap: anywhere; }
.guide-document pre { overflow-x: auto; margin: 17px 0; padding: 20px; border-radius: 10px; background: #172a42; color: #e4edf9; font-size: 12px; line-height: 1.8; }
.guide-document pre code { padding: 0; background: transparent; color: inherit; font-size: inherit; overflow-wrap: normal; }
.guide-document .formula { padding: 16px 20px; border-radius: 8px; background: #f2f6fb; font: 13px/1.9 ui-monospace, SFMono-Regular, Consolas, monospace; overflow-wrap: anywhere; }
.guide-document .small { color: var(--muted); font-size: 12px; }
.guide-document .diagram { overflow-x: auto; margin: 20px 0; padding: 12px; border: 1px solid var(--line); border-radius: 12px; background: #f8fbff; }
.guide-document .diagram svg { display: block; width: 100%; min-width: 720px; height: auto; }
.guide-document .diagram text { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; }
.guide-document .diagram-label { font-size: 17px; font-weight: 750; fill: #17283d; }
.guide-document .diagram-small { font-size: 13px; fill: #405a74; }
.guide-document .diagram-step { font-size: 12px; font-weight: 700; fill: #2058a5; }
.guide-document .diagram-actions { display: flex; flex-wrap: wrap; align-items: center; gap: 12px; margin: 16px 0 8px; }
.guide-document .diagram-whiteboard { background: white; }
.guide-document .diagram-whiteboard svg { min-width: 1060px; }
.guide-document .whiteboard-svg text { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; }
.guide-document .whiteboard-svg .wb-heading { font-size: 29px; font-weight: 800; fill: #17283d; }
.guide-document .whiteboard-svg .wb-title { font-size: 23px; font-weight: 750; fill: #17283d; }
.guide-document .whiteboard-svg .wb-text { font-size: 18px; fill: #344d67; }
.guide-document .whiteboard-svg .wb-small { font-size: 17px; fill: #506176; }
.guide-document .whiteboard-svg .wb-code { font: 16px ui-monospace, SFMono-Regular, Consolas, monospace; fill: #253d57; }
.guide-document .whiteboard-svg .wb-note { font-size: 17px; font-weight: 650; fill: #86500a; }
.guide-document .whiteboard-svg .wb-read { font-size: 17px; font-weight: 750; fill: #2058a5; }
.guide-document .whiteboard-svg .wb-write { font-size: 17px; font-weight: 750; fill: #076b63; }
.guide-document .diagram-viewer { width: min(96vw, 1800px); height: min(92vh, 1200px); max-width: 96vw; max-height: 92vh; padding: 0; border: 1px solid var(--line); border-radius: 12px; color: var(--ink); background: white; }
.guide-document .diagram-viewer[open] { display: flex; flex-direction: column; }
.guide-document .diagram-viewer::backdrop { background: #13263eb8; }
.guide-document .diagram-viewer-header { display: flex; flex: none; align-items: center; justify-content: space-between; gap: 16px; padding: 12px 16px; border-bottom: 1px solid var(--line); }
.guide-document .diagram-viewer-body { flex: 1; min-height: 0; overflow: auto; padding: 16px; background: #f5f8fc; }
.guide-document .diagram-viewer-body svg { display: block; min-width: 100%; max-width: none; height: auto; background: white; }
.guide-document mark.hl { color: #17283d; border-radius: 3px; padding: 0 1px; box-decoration-break: clone; -webkit-box-decoration-break: clone; cursor: pointer; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
.guide-document .hl-pop { position: fixed; z-index: 40; display: none; gap: 7px; padding: 8px 9px; border: 1px solid var(--line); border-radius: 10px; background: var(--paper); box-shadow: 0 8px 24px #13263e40; }
.guide-document .hl-pop.open { display: flex; align-items: center; }
.guide-document .hl-swatch { width: 22px; height: 22px; padding: 0; border: 1px solid #0000002e; border-radius: 6px; cursor: pointer; }
.guide-document .hl-swatch:hover, .guide-document .hl-swatch:focus-visible { outline: 2px solid var(--blue); outline-offset: 1px; }
.guide-document .hl-swatch.current { outline: 2px solid var(--ink); outline-offset: 1px; }
.guide-document .hl-remove { border: 1px solid var(--line); border-radius: 6px; background: white; color: #a12020; font: inherit; font-size: 12px; font-weight: 700; padding: 4px 9px; cursor: pointer; }
.guide-document .hl-remove:hover { background: #fdeaea; }
.guide-document .hl-cross { display: inline-flex; align-items: center; justify-content: center; width: 26px; height: 24px; margin-left: 2px; border: 1px solid var(--line); border-radius: 6px; background: white; color: #a12020; font-size: 13px; font-weight: 800; line-height: 1; cursor: pointer; }
.guide-document .hl-cross:hover:not([disabled]) { background: #fdeaea; }
.guide-document .hl-cross[disabled] { opacity: .4; color: var(--muted); cursor: not-allowed; }
.guide-document .hl-menu { position: fixed; z-index: 40; display: none; flex-direction: column; gap: 9px; width: 244px; padding: 15px; border: 1px solid var(--line); border-radius: 12px; background: var(--paper); box-shadow: 0 12px 30px #13263e40; }
.guide-document .hl-menu.open { display: flex; }
.guide-document .hl-menu h4 { margin: 0; font-size: 14px; }
.guide-document .hl-menu .hl-note { color: var(--muted); font-size: 12px; line-height: 1.5; }
.guide-document .hl-menu .hl-clear { border: 1px solid var(--line); border-radius: 7px; background: white; color: var(--ink); font: inherit; font-size: 12px; font-weight: 700; padding: 8px 10px; cursor: pointer; }
.guide-document .hl-menu .hl-clear:hover:not([disabled]) { background: var(--blue-soft); }
.guide-document .hl-menu .hl-clear[disabled] { opacity: .55; cursor: not-allowed; }
.guide-document details { margin: 13px 0; border: 1px solid var(--line); border-radius: 9px; background: white; }
.guide-document summary { padding: 14px 17px; color: #254b76; font-size: 14px; font-weight: 720; cursor: pointer; }
.guide-document details[open] > summary { border-bottom: 1px solid var(--line); background: #f5f8fc; }
.guide-document .detail-body { padding: 6px 19px 17px; }
.guide-document .checklist { display: grid; gap: 8px; margin-top: 18px; }
.guide-document .checklist label { display: flex; align-items: flex-start; gap: 12px; padding: 12px 14px; border: 1px solid var(--line); border-radius: 8px; font-size: 14px; cursor: pointer; }
.guide-document .checklist input { flex: none; width: 18px; height: 18px; margin: 4px 0 0; accent-color: var(--teal); }
.guide-document .progress { color: var(--teal); font-size: 13px; font-weight: 750; }
.guide-document .closing { margin-top: 30px; color: var(--muted); font-size: 12px; text-align: center; }
@media (min-width: 851px) { .guide-document .sidebar { top: 56px; height: calc(100vh - 56px); } }
@media (min-width: 1800px) { .guide-document { margin: 0 auto; width: 100%; } }
@media (max-width: 1160px) {
  .guide-document .layout { grid-template-columns: 218px minmax(0, 1fr); }
  .guide-document .sidebar { padding: 25px 14px; }
  .guide-document { padding: 26px 24px 45px; }
  .guide-document .hero { padding: 30px; }
  .guide-document section { padding: 25px; }
}
@media (max-width: 850px) {
  .guide-document .layout { display: block; }
  .guide-document .sidebar { position: static; height: auto; padding: 20px; }
  .guide-document .brand { font-size: 21px; }
  .guide-document .sidebar p, .guide-document .sidebar-foot, .guide-document .nav-group { display: none; }
  .guide-document .guide-controls-label { display: none; }
  .guide-document .sidebar nav { display: flex; overflow-x: auto; gap: 5px; margin-top: 15px; padding-bottom: 6px; }
  .guide-document .sidebar nav a { flex: none; border: 1px solid #36516e; font-size: 12px; }
  .guide-document { padding: 20px 16px 40px; }
  .guide-document .hero { padding: 26px 23px; }
  .guide-document section { padding: 24px 20px; }
  .guide-document .lead { font-size: 17px; }
  .guide-document .grid { grid-template-columns: 1fr; }
  .guide-document .mini-flow { flex-direction: column; align-items: stretch; gap: 6px; }
  .guide-document .flow-arrow { align-self: center; transform: rotate(90deg); }
  .guide-document .stage { padding: 17px; }
  .guide-document h2 { font-size: 24px; }
  .guide-document table { min-width: 580px; }
}
@media (prefers-reduced-motion: reduce) { .guide-document { scroll-behavior: auto; } }
@media print {
  @page { size: A4; margin: 14mm; }
  .guide-document { scroll-behavior: auto; }
  .guide-document { background: white; color: black; font-size: 10pt; line-height: 1.5; }
  .guide-document .layout { display: block; }
  .guide-document .sidebar, .guide-document .guide-controls, .guide-document .skip-link, .guide-document .toolbar, .guide-document .hero-note, .guide-document .progress, .guide-document .diagram-actions, .guide-document .diagram-viewer, .guide-document .compact-diagram, .guide-document .hl-pop, .guide-document .hl-menu { display: none !important; }
  .guide-document { max-width: none; padding: 0; }
  .guide-document .hero { padding: 0 0 15pt; border: 0; border-bottom: 2pt solid #2058a5; border-radius: 0; background: white; box-shadow: none; }
  .guide-document h1 { font-size: 28pt; }
  .guide-document .lead { font-size: 12pt; }
  .guide-document section { margin-top: 20pt; padding: 0; border: 0; border-radius: 0; }
  .guide-document h2 { font-size: 18pt; }
  .guide-document h3 { font-size: 13pt; }
  .guide-document h2, .guide-document h3, .guide-document h4, .guide-document summary { break-after: avoid; }
  .guide-document .card, .guide-document .callout, .guide-document blockquote, .guide-document .checklist label { break-inside: avoid; }
  .guide-document .grid { display: block; }
  .guide-document .mini-flow { flex-direction: row; align-items: center; }
  .guide-document .flow-arrow { transform: none; }
  .guide-document .card { margin: 8pt 0; }
  .guide-document .table-wrap, .guide-document .diagram { overflow: visible; }
  .guide-document table { min-width: 0; font-size: 8.5pt; }
  .guide-document thead { display: table-header-group; }
  .guide-document tr { break-inside: avoid; }
  .guide-document th, .guide-document td { padding: 6pt; }
  .guide-document tbody th { min-width: 0; }
  .guide-document pre { white-space: pre-wrap; overflow-wrap: anywhere; background: #f2f5f8; color: black; font-size: 8pt; }
  .guide-document pre code { white-space: pre-wrap; overflow-wrap: anywhere; }
  .guide-document .diagram svg { min-width: 0; }
  .guide-document details { border: 0; margin: 10pt 0; }
  .guide-document summary { padding: 6pt 0; }
  .guide-document .detail-body { padding: 0; }
  .guide-document details > .detail-body { display: block !important; }
  .guide-document details::details-content { content-visibility: visible; }
  .guide-document a { color: inherit; text-decoration: none; }
  .guide-document .small, .guide-document .closing { font-size: 8pt; }
}

.guide-document .source-quote { font-size: 14px; }
.guide-document .reader-status { padding: 10px 20px; color: #7d1c1c; background: #fff0e9; font-size: 13px; }
.guide-document .reader-status[hidden] { display: none; }
@media (max-width: 480px) {
  .guide-document .guide-controls { gap: 6px; padding-inline: 8px; }
  .guide-document .guide-controls > button, .guide-document .guide-controls > .button { padding: 7px 8px; font-size: 11px; }
}
@media print { .guide-document .reader-status { display: none !important; } }
